function normalizeMessagesData(data) {
  if (Array.isArray(data)) {
    return data.reduce((acc, msg) => {
      const date = msg.date || "unknown";
      if (!acc[date]) acc[date] = [];
      acc[date].push(msg);
      return acc;
    }, {});
  }
  return data || {};
}

